reference.setup:
{
    run_pearson <- function(x, y) {
        t <- cor.test(x, y, method = "pearson")
        ci <- t$conf.int
        list(n = length(x), ran = TRUE, r = unname(t$estimate), lower = unname(ci[1]), 
            upper = unname(ci[2]), statistic = unname(t$statistic), df = unname(t$parameter), 
            p = t$p.value)
    }
    run_spearman <- function(x, y) {
        ties <- anyDuplicated(x) > 0 || anyDuplicated(y) > 0
        exact <- !ties && length(x) < 1290
        t <- suppressWarnings(cor.test(x, y, method = "spearman", exact = exact))
        list(n = length(x), ran = TRUE, r = unname(t$estimate), lower = NA_real_, 
            upper = NA_real_, statistic = unname(t$statistic), df = NA_real_, p = t$p.value, 
            exact = exact, ties = ties)
    }
}
